import {catalog,byId,select,restore,toggle} from './catalog.js';
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],page=document.body.dataset.page,params=new URLSearchParams(location.search);
let state=restore(null);try{state=restore(localStorage.getItem('fablebrink'));}catch{}
let undoAction=null,returnFocus=null,activePlayer=null,featureId='last-train',heroManualPause=false;
const systemMotion=matchMedia('(prefers-reduced-motion: reduce)');
const reduced=()=>systemMotion.matches||state.reduced;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const poster=d=>d.id==='last-train'?'assets/train-poster.jpg':d.id==='moon'?'assets/moon-poster.jpg':null;
function artwork(d,extra=''){const src=poster(d);return `<span class="artwork ${extra}" aria-hidden="true">${src?`<img src="${src}" alt="" loading="lazy">`:`<span class="art-face ${d.atlas==='new'?'new-atlas':'old-atlas'}" style="--x:${d.art%3*50}%;--y:${Math.floor(d.art/3)*(d.atlas==='new'?50:100)}%"></span>`}</span>`;}
function persist(){try{localStorage.setItem('fablebrink',JSON.stringify(state));}catch{notify('Saved for this visit only. Browser storage is unavailable.');}}
function notify(message,undo=null){$('#toast-message').textContent=message;$('#toast').hidden=false;undoAction=undo;$('#undo').hidden=!undo;}
$('#dismiss').onclick=()=>$('#toast').hidden=true;$('#undo').onclick=()=>{const focused=document.activeElement=== $('#undo');undoAction?.();$('#toast').hidden=true;if(focused)($('#catalog-grid button')||$('#preferences')).focus();};
function sync(){all('[data-save]').forEach(b=>{const d=byId(b.dataset.save);if(!d)return;const yes=state.saved.includes(d.id);b.textContent=yes?'✓ Saved':'+ My list';b.setAttribute('aria-pressed',String(yes));b.setAttribute('aria-label',`${yes?'Remove':'Save'} ${d.title}${yes?' from my list':''}`);});$('#list-count').textContent=state.saved.length;}
function save(id){const old=[...state.saved],removed=old.includes(id);state.saved=toggle(old,id);persist();const focusInGrid=$('#catalog-grid')?.contains(document.activeElement);if(page==='list'){renderCatalog();if(focusInGrid)($('#catalog-grid button')||$('#query')).focus();}sync();notify(`${byId(id).title} ${removed?'removed from':'saved to'} your list.`,()=>{state.saved=old;persist();if(page==='list')renderCatalog();sync();});}
function bind(root=document){root.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>save(b.dataset.save));root.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>play(b.dataset.play));sync();}
function card(d,style='wide'){return `<article class="film-card ${style}"><a class="art-link" href="title.html?id=${d.id}" aria-label="Explore ${esc(d.title)}">${artwork(d)}${d.preview?'<span class="preview-badge">ANIMATED PREVIEW</span>':''}</a><div class="card-copy"><p class="card-meta">${d.format} <span>·</span> ${d.genre}</p><h3><a href="title.html?id=${d.id}">${esc(d.title)}</a></h3><p class="card-tag">${esc(d.tag)}</p><button data-save="${d.id}" class="save-button"></button></div></article>`;}
const collections=[{title:'When the city falls asleep.',sub:'Some stories only begin after dark.',ids:['last-train','blue-hour','night-shift','midnight-kitchen'],link:'browse.html?collection=night',kind:'wide'},{title:'A little wonder goes a long way.',sub:'For the part of you that still looks up.',ids:['moon','islands','paper-birds','clockwork'],link:'browse.html?mood=Wonder',kind:'portrait'},{title:'A softer landing.',sub:'Small moments. A little warmth. Room to breathe.',ids:['coast','autumn','cat-cafe','soggy'],link:'browse.html?mood=Comfort',kind:'wide'}];
function shelf(c){return `<section class="shelf"><div class="shelf-heading"><div><p class="eyebrow">THE FABLEBRINK COLLECTIONS</p><h2>${c.title}</h2><p>${c.sub}</p></div><a href="${c.link}">Explore collection ↗</a></div><div class="shelf-grid">${c.ids.map(id=>card(byId(id),c.kind)).join('')}</div></section>`;}
function hero(){const d=byId(featureId),v=$('#hero-video');v.pause();v.poster=poster(d);v.src=d.preview;v.load();$('#feature-title').innerHTML=d.id==='last-train'?'After the<br>Last Train':'The Moon Keeps<br>a Garden';$('#feature-tag').textContent=d.tag;$('#feature-label').textContent=`THE FABLEBRINK SELECTION | ${d.id==='last-train'?'01':'02'}`;$('#feature-details').href='title.html?id='+d.id;$('#feature-save').dataset.save=d.id;$('#feature-availability').textContent=`Original animated preview | ${d.duration} seconds`;$('#feature-watch').onclick=()=>play(d.id);all('[data-feature]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.feature===d.id)));sync();if(!reduced()&&!heroManualPause)v.play().catch(()=>{});motionLabel();}
function motionLabel(){if($('#hero-motion'))$('#hero-motion').textContent=$('#hero-video').paused?'Play background motion':'Pause background motion';}
function continueShelf(){const target=$('#continue-section');if(!target)return;const entries=catalog.filter(d=>d.preview&&(state.progress[d.id]||0)>0);target.hidden=!entries.length;target.innerHTML=`<div class="shelf-heading"><h2>Pick up where you left off.</h2></div><div class="continue-grid">${entries.map(d=>{const t=state.progress[d.id]||0,done=t>=d.duration-.5;return `<article class="continue-card">${artwork(d)}<div><h3>${esc(d.title)}</h3><p>${done?'Preview watched':Math.floor(t)+' of '+d.duration+' seconds'} | Preview</p><progress max="${d.duration}" value="${t}" aria-label="${esc(d.title)} preview progress"></progress><button data-play="${d.id}">${done?'Watch again':'Continue preview'} ▶</button></div></article>`;}).join('')}</div>`;bind(target);}
function initHome(){$('#collections').innerHTML=collections.map(shelf).join('');const d=byId('moon');$('#editorial-spotlight').innerHTML=`<section class="editorial-feature"><a href="title.html?id=moon" aria-label="Explore The Moon Keeps a Garden">${artwork(d)}</a><div><p class="eyebrow">IN FOCUS | THE MOON KEEPS A GARDEN</p><h2>Even far from home,<br>something grows.</h2><p>${esc(d.editorial)}</p><button data-play="moon" class="primary">▶ Watch preview</button><a class="inline-link" href="title.html?id=moon">Step inside this world ↗</a></div></section>`;all('[data-feature]').forEach(b=>b.onclick=()=>{featureId=b.dataset.feature;hero();});$('#hero-motion').onclick=()=>{const v=$('#hero-video');if(v.paused){heroManualPause=false;v.play().catch(()=>notify('Background video could not play. Try the preview player.'));}else{heroManualPause=true;v.pause();}};$('#hero-video').addEventListener('play',motionLabel);$('#hero-video').addEventListener('pause',motionLabel);new IntersectionObserver(entries=>{for(const entry of entries)if(!entry.isIntersecting)$('#hero-video').pause();},{threshold:.1}).observe($('#hero-video'));bind();hero();continueShelf();}
function renderCatalog(){let rows=select({query:$('#query').value,format:$('#format').value,genre:$('#genre').value,mood:$('#mood').value,savedOnly:page==='list',saved:state.saved});if(params.get('collection')==='night')rows=rows.filter(d=>collections[0].ids.includes(d.id));$('#results').textContent=`${rows.length} ${rows.length===1?'title':'titles'}${$('#mood').value!=='All'?' | Picked because you chose '+$('#mood').value:''}`;$('#catalog-grid').innerHTML=rows.length?rows.map(d=>card(d,'portrait')).join(''):`<div class="empty"><h2>${page==='list'&&!state.saved.length?'Your next world is still out there.':'Nothing here just yet.'}</h2><p>${page==='list'&&!state.saved.length?'Save a title while you explore. You will find it here when you return.':'Try another search or clear your filters.'}</p><a href="browse.html">Explore every title ↗</a><button id="empty-clear">Clear filters</button></div>`;bind($('#catalog-grid'));$('#empty-clear')?.addEventListener('click',()=>{$('#filters').reset();$('#query').focus();});}
function initCatalog(){const initial=['Film','Series'].includes(page)?page:'All';$('#format').value=initial;if(['Wonder','Comfort','Intensity'].includes(params.get('mood')))$('#mood').value=params.get('mood');$('#filters').onsubmit=e=>e.preventDefault();['query','format','genre','mood'].forEach(id=>$('#'+id).addEventListener(id==='query'?'input':'change',renderCatalog));$('#filters').onreset=()=>setTimeout(()=>{params.delete('collection');params.delete('mood');history.replaceState(null,'',location.pathname);$('#format').value=initial;renderCatalog();},0);renderCatalog();}
function initTitle(){const d=byId(params.get('id'));if(!d){$('#title-content').innerHTML='<section class="collection-heading"><h1>That story is not here.</h1><p>It may have moved, or the link may be incomplete.</p><a href="browse.html">Explore the collection ↗</a></section>';return;}document.title=d.title+' | Fablebrink';const related=catalog.filter(x=>x.id!==d.id&&(x.mood===d.mood||x.genre===d.genre)).slice(0,4);$('#title-content').innerHTML=`<section class="title-hero">${artwork(d)}<div class="title-shade"></div><div class="title-heading"><a class="back-link" href="${d.format==='Film'?'films':'series'}.html">← Back to ${d.format.toLowerCase()}s</a><p class="eyebrow">${d.format.toUpperCase()} | ${d.genre.toUpperCase()} | ${d.mood.toUpperCase()}</p><h1>${esc(d.title)}</h1><p>${esc(d.tag)}</p><div class="feature-actions">${d.preview?`<button data-play="${d.id}" class="primary">▶ Watch preview</button>`:'<span class="unavailable">Preview not available</span>'}<button data-save="${d.id}" class="save-button"></button></div><p class="availability">${d.preview?d.duration+' second original animated preview. Full '+(d.format==='Film'?'film':'episodes')+' not available.':'Original title concept. Full '+(d.format==='Film'?'film':'episodes')+' not available.'}</p></div></section><section class="title-editorial"><div><p class="eyebrow">THE STORY</p><h2>${esc(d.tag)}</h2><p>${esc(d.description)}</p></div><aside><p class="eyebrow">WHY THIS WORLD</p><p>${esc(d.editorial)}</p><dl><div><dt>Format</dt><dd>${d.format}</dd></div><div><dt>Genre</dt><dd>${d.genre}</dd></div><div><dt>Feeling</dt><dd>${d.mood}</dd></div></dl></aside></section>${d.format==='Series'?`<section class="episodes"><div class="shelf-heading"><h2>Inside the series.</h2><label class="check-label"><input id="show-episodes" type="checkbox" ${state.spoilers?'checked':''}>Show proposed episode names</label></div><p class="muted">Proposed episode order. Full episodes are not available.</p><div id="episode-list"></div></section>`:''}<section class="shelf related"><div class="shelf-heading"><div><p class="eyebrow">KEEP EXPLORING</p><h2>If this world speaks to you.</h2><p>More stories with a similar mood or genre.</p></div></div><div class="shelf-grid">${related.map(x=>card(x)).join('')}</div></section><section class="credits"><details><summary>About this title</summary><p>${d.origin.startsWith('Offbeat')?'A proposed visual treatment for an OffbeatPanels story. Artwork, summaries, and episode names are not established series canon.':'An original fictional title created for this independent portfolio project.'} The catalog does not claim a Japanese production studio, cast, release date, awards, or licensed full length content.</p></details></section>`;function episodes(){$('#episode-list').innerHTML=d.episodes.map((e,i)=>`<div class="episode"><span>${String(i+1).padStart(2,'0')}</span><h3>${state.spoilers?esc(e):'Episode '+(i+1)}</h3><span>Not available</span></div>`).join('');}if($('#show-episodes')){episodes();$('#show-episodes').onchange=e=>{state.spoilers=e.target.checked;persist();episodes();};}bind();}
function openDialog(html){returnFocus=document.activeElement;$('#hero-video')?.pause();$('#dialog-content').innerHTML=html;$('#dialog').showModal();$('#close').focus();}
$('#close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('close',()=>{activePlayer?.pause();activePlayer=null;$('#dialog-content').innerHTML='';if(returnFocus?.isConnected)returnFocus.focus();continueShelf();});
function play(id){const d=byId(id);if(!d?.preview)return;openDialog(`<div class="player"><p class="eyebrow">FABLEBRINK | ORIGINAL ANIMATED PREVIEW</p><h2 id="dialog-title">${esc(d.title)}</h2><video id="player-video" controls playsinline preload="metadata" poster="${poster(d)}"><source src="${d.preview}" type="video/mp4"><track kind="captions" label="English sound descriptions" srclang="en" src="assets/${id==='moon'?'moon':'train'}.vtt" default></video><p id="player-status" role="status">Press play to start. Sound is controlled by the player.</p><div class="player-tools"><button id="rewind">Back 5 seconds</button><button id="restart">Start again</button><label>Speed<select id="speed"><option value="1">1×</option><option value="0.75">0.75×</option><option value="1.5">1.5×</option></select></label></div><details><summary>Read the visual description</summary><p>${id==='moon'?'A botanist walks among violet flowers in a lunar greenhouse. A gloved hand reaches toward a glowing flower. The view opens onto a glass dome surrounded by the lunar landscape, with Earth above.':'A courier in a red jacket walks along an elevated station platform with a luminous white fox. A train moves behind them. The fox turns and bounds toward the camera.'}</p></details><p class="muted">${d.duration} second animated preview | Full ${d.format==='Film'?'film':'episodes'} not available.</p><a href="title.html?id=${d.id}">Explore the story ↗</a></div>`);const v=$('#player-video');activePlayer=v;v.onloadedmetadata=()=>{const p=state.progress[id]||0;if(p<v.duration-.5)v.currentTime=p;};let last=0;function remember(){if(Number.isFinite(v.currentTime)){state.progress[id]=Math.min(d.duration,v.currentTime);persist();}}v.ontimeupdate=()=>{if(Math.abs(v.currentTime-last)>=1){last=v.currentTime;remember();}};v.onpause=remember;v.onended=()=>{remember();$('#player-status').textContent='Preview complete. Watch again, or explore the story.';};v.onerror=()=>{$('#player-status').textContent='The preview could not load. Use Start again to retry, or read the visual description.';};$('#rewind').onclick=()=>v.currentTime=Math.max(0,v.currentTime-5);$('#restart').onclick=()=>{if(v.error)v.load();v.currentTime=0;v.play().catch(()=>{$('#player-status').textContent='Playback could not start. Try the native play control.';});};$('#speed').onchange=e=>v.playbackRate=Number(e.target.value);}
function applyMotion(){document.documentElement.classList.toggle('reduced',reduced());if(reduced())$('#hero-video')?.pause();}
systemMotion.addEventListener('change',applyMotion);$('#preferences').onclick=()=>{openDialog(`<div class="prefs"><p class="eyebrow">MAKE YOURSELF AT HOME</p><h2 id="dialog-title">Viewing preferences</h2><label class="check-label"><input id="reduce-motion" type="checkbox" ${state.reduced?'checked':''}>Reduce interface and background motion</label><p>Your system motion preference is also respected. Preview playback always starts with your choice. Background scenes are muted and have a pause control.</p><h3>Your privacy</h3><p>Saved titles, preview progress, and viewing preferences stay in this browser. There are no accounts or advertising trackers.</p><button id="clear-progress">Clear preview progress</button><p id="preference-status" role="status"></p></div>`);$('#reduce-motion').onchange=e=>{state.reduced=e.target.checked;persist();applyMotion();};$('#clear-progress').onclick=()=>{state.progress={};persist();$('#preference-status').textContent='Preview progress cleared.';continueShelf();};};
all('[data-nav]').forEach(a=>{if(a.dataset.nav===page)a.setAttribute('aria-current','page');});applyMotion();if(page==='home')initHome();else if(page==='title')initTitle();else initCatalog();sync();
